// loop owns this entry's reference count. A join is acknowledged by the
// receive itself, so an acquirer knows its reference is counted before it
// returns, and the loop never blocks on a caller that has walked away.
//
// It starts at one, not zero: whoever built this entry holds the first
// reference by construction and never sends a join for it. Starting at
// zero would leave an entry whose creator gave up before joining alive
// with no reference and no timer armed — live forever, held by nobody.
func (e *userIDEntry) loop() {
	refs := 1
	var timer *time.Timer
	var linger <-chan time.Time
	stopTimer := func() {
		if timer != nil {
			timer.Stop()
			timer = nil
		}
		linger = nil
	}
	for {
		// Checked before the blocking select, so that once Shutdown has
		// closed quit this loop stops accepting joins instead of racing
		// them. A join and a quit both ready in one select is a coin
		// flip, and losing it hands an acquirer an instance this
		// iteration is about to tear down.
		select {
		case <-e.scope.quit:
			stopTimer()
			e.drainRefs(refs)
			e.evict()
			return
		default:
		}

		select {
		case <-e.joins:
			refs++
			stopTimer()
		case <-e.leaves:
			refs--
			if refs == 0 {
				// The window before eviction. Without it a short handler
				// takes the count 0->1->0 per request and the instance is
				// rebuilt every time, losing whatever in-memory state made
				// it worth sharing.
				stopTimer()
				timer = time.NewTimer(e.scope.linger)
				linger = timer.C
			}
		case <-linger:
			timer, linger = nil, nil
			e.evict()
			return
		case <-e.scope.quit:
			stopTimer()
			e.drainRefs(refs)
			e.evict()
			return
		}
	}
}

// drainRefs waits for the holders outstanding when Shutdown arrived to
// give their references back before teardown starts. A counted
// reference is a promise that the instance stays usable until it is
// released, and evicting under a live holder would break that promise
// for the one caller who did everything right: acquired successfully,
// a moment before someone else called Shutdown.
//
// In the ordinary case there is nothing to wait for. Shutdown stops
// nodes in reverse level order, so whatever depends on this scope has
// already been drained and stopped, its handlers have returned and
// their releases have already landed.
//
// Bounded by one stop budget, because a caller who never releases must
// not hold shutdown open. Overrunning that bound is recorded in
// drainResult, which teardown merges, so the entry comes back
// abandoned: the report is the only place a promise broken this way
// could show, and a clean one would hide it entirely.
func (e *userIDEntry) drainRefs(refs int) {
	if refs <= 0 {
		return
	}
	budget := time.NewTimer(servo.DefaultStopBudget)
	defer budget.Stop()
	for refs > 0 {
		select {
		case <-e.leaves:
			refs--
		case <-budget.C:
			err := fmt.Errorf("servo: torn down with %d reference(s) still held after %s", refs, servo.DefaultStopBudget)
			e.drainResult = servo.NodeResult{Name: e.name(), Status: servo.StatusAbandoned, Err: err}
			return
		}
	}
}

// evict removes the key from the map BEFORE announcing the entry's death.
// Reversed, an acquirer that lost the join race would retry, look the key
// up, find this same dying entry, and never terminate.
func (e *userIDEntry) evict() {
	e.scope.beginTeardown(e)
	close(e.dead)
	e.stopResult = e.teardown()
	e.scope.endTeardown(e, e.stopResult)
	close(e.torn)
}

